          {"name": "Colorectal cancer", "description": "Adenocarcinoma arising in the colon or rectum, often from preexisting adenomatous polyps.", "aliases": ["Colon cancer", "Rectal cancer", "CRC"], "causes": ["adenomatous polyps", "Lynch syndrome", "familial adenomatous polyposis", "diet", "obesity", "age"], "symptoms": ["change in bowel habits", "rectal bleeding", "abdominal pain", "unexplained weight loss", "iron deficiency anemia"], "treatment": "Surgery; FOLFOX/FOLFIRI chemotherapy; bevacizumab or cetuximab; radiotherapy for rectal cancer", "prevalence": "1.93 million new cases per year globally", "is_rare": 0, "sources": ["https://www.cancer.gov/types/colorectal"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/29680491/"], "icd11_code": "2B90"},
          {"name": "Prostate cancer", "description": "Adenocarcinoma of the prostate gland, most common cancer in men.", "aliases": ["Prostate adenocarcinoma", "Prostatic carcinoma"], "causes": ["age", "family history", "BRCA mutations", "African ancestry", "high androgen levels"], "symptoms": ["urinary frequency", "weak stream", "hematuria", "hematospermia", "bone pain in metastatic disease"], "treatment": "Active surveillance for low-grade; radical prostatectomy; radiation; androgen deprivation therapy; docetaxel chemotherapy", "prevalence": "1.4 million new cases per year globally", "is_rare": 0, "sources": ["https://www.cancer.gov/types/prostate"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/29859051/"], "icd11_code": "2C82"},
          {"name": "Stomach cancer", "description": "Adenocarcinoma of the stomach frequently associated with H. pylori infection and dietary factors.", "aliases": ["Gastric cancer", "Gastric adenocarcinoma"], "causes": ["Helicobacter pylori infection", "salt-preserved foods", "smoking", "family history", "CDH1 mutation"], "symptoms": ["epigastric pain", "dysphagia", "early satiety", "weight loss", "vomiting", "hematemesis"], "treatment": "Gastrectomy with D2 lymphadenectomy; perioperative FLOT chemotherapy; HER2-targeted therapy for HER2+ disease", "prevalence": "1.09 million new cases per year globally", "is_rare": 0, "sources": ["https://www.cancer.gov/types/stomach"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/23523399/"], "icd11_code": "2B72"},
          {"name": "Liver cancer", "description": "Primary malignancy of the liver most commonly hepatocellular carcinoma associated with cirrhosis.", "aliases": ["Hepatocellular carcinoma", "HCC", "Hepatic carcinoma"], "causes": ["hepatitis B and C", "alcoholic cirrhosis", "nonalcoholic steatohepatitis", "aflatoxin exposure"], "symptoms": ["right upper quadrant pain", "jaundice", "ascites", "weight loss", "abdominal mass"], "treatment": "Surgical resection or transplant for early disease; sorafenib, lenvatinib, atezolizumab+bevacizumab for advanced", "prevalence": "906,000 new cases per year globally", "is_rare": 0, "sources": ["https://www.cancer.gov/types/liver"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/29222504/"], "icd11_code": "2C12"},
          {"name": "Pancreatic cancer", "description": "Highly lethal ductal adenocarcinoma of the pancreas with typically late presentation.", "aliases": ["Pancreatic ductal adenocarcinoma", "PDAC", "Exocrine pancreatic cancer"], "causes": ["smoking", "obesity", "type 2 diabetes", "chronic pancreatitis", "BRCA2 mutations", "KRAS mutations"], "symptoms": ["painless jaundice", "weight loss", "abdominal pain", "new-onset diabetes", "steatorrhea"], "treatment": "Whipple procedure for resectable disease; FOLFIRINOX or gemcitabine+nab-paclitaxel chemotherapy", "prevalence": "496,000 new cases per year globally", "is_rare": 0, "sources": ["https://www.cancer.gov/types/pancreatic"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/29630932/"], "icd11_code": "2C10"},
          {"name": "Cervical cancer", "description": "Squamous cell carcinoma or adenocarcinoma of the cervix caused primarily by HPV infection.", "aliases": ["Cervical carcinoma", "HPV-related cervical cancer"], "causes": ["HPV types 16 and 18", "smoking", "immunosuppression", "multiple sexual partners"], "symptoms": ["abnormal vaginal bleeding", "postcoital bleeding", "vaginal discharge", "pelvic pain"], "treatment": "Surgery for early stage; chemoradiation with cisplatin for locally advanced; HPV vaccination for prevention", "prevalence": "604,000 new cases per year globally", "is_rare": 0, "sources": ["https://www.who.int/news-room/fact-sheets/detail/cervical-cancer"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/30060628/"], "icd11_code": "2C77"},
          {"name": "Ovarian cancer", "description": "Malignancy of the ovary most commonly epithelial ovarian carcinoma, often presenting at advanced stage.", "aliases": ["Ovarian carcinoma", "Epithelial ovarian cancer"], "causes": ["BRCA1/2 mutations", "Lynch syndrome", "family history", "endometriosis", "nulliparity"], "symptoms": ["bloating", "pelvic pain", "urinary urgency", "difficulty eating", "ascites"], "treatment": "Cytoreductive surgery plus carboplatin/paclitaxel chemotherapy; PARP inhibitors for BRCA-mutated disease", "prevalence": "314,000 new cases per year globally", "is_rare": 0, "sources": ["https://www.cancer.gov/types/ovarian"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/31910182/"], "icd11_code": "2C73"},
          {"name": "Bladder cancer", "description": "Urothelial carcinoma of the bladder, strongly associated with tobacco smoking.", "aliases": ["Urothelial carcinoma", "Transitional cell carcinoma of bladder"], "causes": ["smoking", "occupational carcinogen exposure", "chronic bladder infection", "cyclophosphamide"], "symptoms": ["painless hematuria", "dysuria", "urinary frequency", "pelvic pain"], "treatment": "TURBT for non-muscle invasive; radical cystectomy for muscle-invasive; cisplatin-based chemotherapy", "prevalence": "573,000 new cases per year globally", "is_rare": 0, "sources": ["https://www.cancer.gov/types/bladder"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/22453969/"], "icd11_code": "2C94"},
          {"name": "Kidney cancer", "description": "Renal cell carcinoma arising from renal tubular epithelium, often detected incidentally.", "aliases": ["Renal cell carcinoma", "RCC", "Hypernephroma"], "causes": ["smoking", "obesity", "hypertension", "VHL syndrome", "polycystic kidney disease"], "symptoms": ["hematuria", "flank pain", "abdominal mass", "paraneoplastic syndromes", "often incidental finding"], "treatment": "Radical or partial nephrectomy; sunitinib, pazopanib for metastatic disease; immunotherapy combinations", "prevalence": "431,000 new cases per year globally", "is_rare": 0, "sources": ["https://www.cancer.gov/types/kidney"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/25058175/"], "icd11_code": "2C90"},
          {"name": "Thyroid cancer", "description": "Malignant tumor of the thyroid gland including papillary, follicular, medullary, and anaplastic subtypes.", "aliases": ["Thyroid carcinoma", "Papillary thyroid cancer"], "causes": ["radiation exposure", "family history", "RET proto-oncogene mutations", "MEN2 syndrome"], "symptoms": ["thyroid nodule", "neck lump", "hoarseness", "dysphagia", "cervical lymphadenopathy"], "treatment": "Total thyroidectomy; radioactive iodine for differentiated cancers; levothyroxine suppression therapy", "prevalence": "586,000 new cases per year globally", "is_rare": 0, "sources": ["https://www.cancer.gov/types/thyroid"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/28885440/"], "icd11_code": "2D10"},
          {"name": "Melanoma", "description": "Malignant neoplasm arising from melanocytes, the most dangerous form of skin cancer.", "aliases": ["Malignant melanoma", "Cutaneous melanoma"], "causes": ["UV radiation", "sunburn history", "fair skin", "BRAF mutations", "family history"], "symptoms": ["changing mole", "asymmetry, border irregularity, color variation, diameter >6mm, evolution (ABCDE)", "ulceration"], "treatment": "Wide local excision; sentinel lymph node biopsy; BRAF/MEK inhibitors; PD-1 checkpoint inhibitors", "prevalence": "325,000 new cases per year globally", "is_rare": 0, "sources": ["https://www.cancer.gov/types/skin"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/29571611/"], "icd11_code": "2C30"},
          {"name": "Head and neck squamous cell carcinoma", "description": "Squamous cell carcinoma arising from mucosal surfaces of the oral cavity, pharynx, or larynx.", "aliases": ["HNSCC", "Oral cancer", "Laryngeal cancer", "Oropharyngeal cancer"], "causes": ["tobacco smoking", "alcohol", "HPV type 16 for oropharynx", "betel nut chewing"], "symptoms": ["persistent hoarseness", "dysphagia", "neck mass", "oral ulcer", "otalgia", "trismus"], "treatment": "Surgery or radiotherapy for early stage; concurrent cisplatin-chemoradiation for locally advanced", "prevalence": "890,000 new cases per year globally", "is_rare": 0, "sources": ["https://www.cancer.gov/types/head-and-neck"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/28105456/"], "icd11_code": "2C22"},
          {"name": "Esophageal cancer", "description": "Malignant tumor of the esophagus including squamous cell carcinoma and adenocarcinoma subtypes.", "aliases": ["Esophageal carcinoma", "Oesophageal cancer"], "causes": ["Barrett esophagus", "GERD", "smoking", "alcohol", "achalasia", "caustic injury"], "symptoms": ["progressive dysphagia", "odynophagia", "weight loss", "chest pain", "regurgitation"], "treatment": "Esophagectomy for resectable disease; neoadjuvant chemoradiation with CROSS protocol; pembrolizumab for advanced", "prevalence": "604,000 new cases per year globally", "is_rare": 0, "sources": ["https://www.cancer.gov/types/esophageal"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/31857048/"], "icd11_code": "2B70"}
