          {"name": "Non-Hodgkin lymphoma", "description": "Heterogeneous group of lymphoid malignancies including diffuse large B-cell and follicular lymphoma.", "aliases": ["NHL", "B-cell lymphoma", "T-cell lymphoma"], "causes": ["EBV", "HTLV-1", "HIV", "immunosuppression", "autoimmune diseases", "chromosomal translocations"], "symptoms": ["lymphadenopathy", "B symptoms", "extranodal involvement", "cytopenias"], "treatment": "R-CHOP for DLBCL; various regimens depending on histology; CAR-T cell therapy for relapsed disease", "prevalence": "500,000 new cases per year globally", "is_rare": 0, "sources": ["https://www.cancer.gov/types/lymphoma/patient/adult-nhl-treatment-pdq"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/25307644/"], "icd11_code": "2A85"},
