          {"name": "Sickle cell anemia", "description": "Hereditary hemolytic anemia caused by HbS mutation leading to vaso-occlusive crises and organ damage.", "aliases": ["Sickle cell disease", "HbSS disease", "Drepanocytosis"], "causes": ["HBB gene Glu6Val mutation (homozygous)"], "symptoms": ["pain crises", "dactylitis", "acute chest syndrome", "stroke", "splenic sequestration", "chronic hemolytic anemia"], "treatment": "Hydroxyurea; pain management; transfusions; allogeneic SCT; voxelotor and crizanlizumab", "prevalence": "300,000 births affected per year globally", "is_rare": 0, "sources": ["https://www.cdc.gov/ncbddd/sicklecell/index.html"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/27398137/"], "icd11_code": "3A51.1"},
          {"name": "Thalassemia", "description": "Inherited hemoglobin disorders with reduced or absent alpha or beta globin chain synthesis.", "aliases": ["Beta-thalassemia", "Alpha-thalassemia", "Cooley anemia"], "causes": ["HBB or HBA1/2 gene mutations reducing globin chain synthesis"], "symptoms": ["severe anemia", "hepatosplenomegaly", "bone deformities", "growth retardation", "iron overload"], "treatment": "Regular transfusions; iron chelation therapy; allogeneic SCT; luspatercept for beta-thalassemia", "prevalence": "100 million carriers worldwide; 40,000 severe cases born per year", "is_rare": 0, "sources": ["https://www.who.int/genomics/public/geneticdiseases/en/index2.html"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/28668203/"], "icd11_code": "3A51.0"},
