def insert_node(cur, parent_id, level, name, description, aliases, causes, symptoms,
                treatment, prevalence, is_rare, sources, research_links, icd11_code):
    cur.execute(
        """INSERT INTO nodes (parent_id, level, name, description, aliases, causes, symptoms,
           treatment, prevalence, is_rare, sources, research_links, icd11_code)
           VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (parent_id, level,
         name, description,
         json.dumps(aliases), json.dumps(causes), json.dumps(symptoms),
         treatment, prevalence, is_rare,
         json.dumps(sources), json.dumps(research_links), icd11_code)
    )
    return cur.lastrowid



