          {"name": "Osteoporosis", "description": "Metabolic bone disease with reduced bone mineral density and microarchitectural deterioration increasing fracture risk.", "aliases": ["Bone thinning disease", "Porous bone disease"], "causes": ["aging", "menopause", "low calcium and vitamin D", "corticosteroids", "smoking", "low BMI", "secondary: hyperparathyroidism, malabsorption"], "symptoms": ["often asymptomatic until fracture", "fragility fractures of hip, spine, wrist", "height loss", "kyphosis", "back pain from vertebral fractures"], "treatment": "Calcium and vitamin D supplementation; bisphosphonates (alendronate, risedronate) first-line; denosumab; teriparatide for severe; romosozumab", "prevalence": "200 million women worldwide", "is_rare": 0, "sources": ["https://www.niams.nih.gov/health-topics/osteoporosis"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/27720189/"], "icd11_code": "FB83"},
          {"name": "Ankylosing spondylitis", "description": "Seronegative spondyloarthropathy with axial inflammation causing progressive spinal fusion.", "aliases": ["AS", "Axial spondyloarthritis", "Bechterew disease"], "causes": ["HLA-B27 in 90% of cases", "genetic predisposition", "gut dysbiosis association"], "symptoms": ["inflammatory back pain worse at night and morning stiffness", "sacroiliitis", "progressive bamboo spine", "uveitis", "enthesitis", "peripheral arthritis"], "treatment": "NSAIDs first-line; anti-TNF biologics; secukinumab (anti-IL-17); ixekizumab; physical therapy", "prevalence": "0.1-0.5% of population", "is_rare": 0, "sources": ["https://www.niams.nih.gov/health-topics/ankylosing-spondylitis"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/28228494/"], "icd11_code": "FA91"},
          {"name": "Fibromyalgia", "description": "Chronic widespread pain disorder with central sensitization and associated cognitive and sleep disturbance.", "aliases": ["FMS", "Fibromyalgia syndrome", "Widespread pain syndrome"], "causes": ["central sensitization", "genetic polymorphisms in serotonin and dopamine pathways", "stress", "trauma", "infections as triggers"], "symptoms": ["widespread musculoskeletal pain", "fatigue", "fibrofog", "sleep disturbance", "tender points", "comorbid anxiety and depression"], "treatment": "Multidisciplinary: aerobic exercise; CBT; duloxetine or milnacipran; pregabalin; amitriptyline; sleep hygiene", "prevalence": "2-4% of population; 7:1 female to male ratio", "is_rare": 0, "sources": ["https://www.niams.nih.gov/health-topics/fibromyalgia"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/29198241/"], "icd11_code": "MG30.01"},
          {"name": "Systemic sclerosis", "description": "Systemic autoimmune disease with fibrosis of skin and internal organs due to vasculopathy and immune activation.", "aliases": ["Scleroderma", "SSc", "CREST syndrome"], "causes": ["autoimmune: anti-Scl-70, anti-centromere, anti-RNA polymerase III antibodies", "endothelial injury triggering fibrosis"], "symptoms": ["Raynaud phenomenon", "skin thickening and tightening", "interstitial lung disease", "pulmonary hypertension", "GI dysmotility", "renal crisis"], "treatment": "No cure; organ-specific: bosentan for PAH; nintedanib or mycophenolate for ILD; calcium channel blockers for Raynaud; ACE inhibitors for renal crisis", "prevalence": "10-20 per 100,000", "is_rare": 0, "sources": ["https://www.niams.nih.gov/health-topics/scleroderma"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/29250026/"], "icd11_code": "LD84"},
          {"name": "Polymyositis", "description": "Idiopathic inflammatory myopathy with proximal muscle weakness and elevated muscle enzymes.", "aliases": ["PM", "Inflammatory myopathy"], "causes": ["autoimmune T-cell mediated muscle inflammation", "anti-Jo-1 antibodies in subset with antisynthetase syndrome"], "symptoms": ["symmetric proximal muscle weakness", "elevated CK and aldolase", "dysphagia", "ILD in antisynthetase syndrome", "rarely cardiac involvement"], "treatment": "Corticosteroids first-line; methotrexate or azathioprine as steroid-sparing; IVIG for refractory cases; physical therapy", "prevalence": "5-10 per million per year", "is_rare": 1, "sources": ["https://www.niams.nih.gov/health-topics/polymyositis"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/26059136/"], "icd11_code": "5C22.2"},
          {"name": "Dermatomyositis", "description": "Idiopathic inflammatory myopathy with characteristic skin rashes alongside proximal muscle weakness.", "aliases": ["DM", "Inflammatory myopathy with skin involvement"], "causes": ["autoimmune; anti-Mi-2, anti-MDA5, anti-TIF1-gamma antibodies; paraneoplastic in adults"], "symptoms": ["Gottrons papules over knuckles", "heliotrope rash around eyes", "shawl sign", "proximal muscle weakness", "ILD in anti-MDA5 subset", "calcinosis"], "treatment": "Corticosteroids; methotrexate or azathioprine; IVIG; rituximab for refractory; screen for malignancy in adults", "prevalence": "1 in 100,000 per year", "is_rare": 1, "sources": ["https://www.niams.nih.gov/health-topics/polymyositis"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/26059136/"], "icd11_code": "5C22.1"},
          {"name": "Paget disease of bone", "description": "Chronic metabolic bone disorder with focal areas of excessive and disorganized bone remodeling.", "aliases": ["Osteitis deformans", "Pagets disease"], "causes": ["paramyxovirus environmental trigger in genetically predisposed; mutations in SQSTM1 gene"], "symptoms": ["often asymptomatic", "bone pain", "deformity: bowing of legs, skull enlargement", "hearing loss", "high-output cardiac failure", "sarcomatous transformation rare"], "treatment": "Bisphosphonates: zoledronic acid single IV infusion preferred; calcitonin alternative; pain management", "prevalence": "2-3% of adults over 55 in UK and USA", "is_rare": 0, "sources": ["https://www.niams.nih.gov/health-topics/pagets-disease-bone"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/24703099/"], "icd11_code": "FB81"},
          {"name": "Osteogenesis imperfecta", "description": "Genetic connective tissue disorder with fragile bones from defective type I collagen synthesis.", "aliases": ["Brittle bone disease", "OI", "Lobstein syndrome"], "causes": ["mutations in COL1A1 or COL1A2 genes encoding type I collagen; autosomal dominant in most types"], "symptoms": ["recurrent fragility fractures from minimal trauma", "blue sclerae", "hearing loss", "dentinogenesis imperfecta", "short stature", "easy bruising"], "treatment": "Bisphosphonates to reduce fracture rate; surgical rodding of long bones; physical therapy; hearing aids", "prevalence": "6-7 per 100,000", "is_rare": 1, "sources": ["https://www.niams.nih.gov/health-topics/osteogenesis-imperfecta"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/27717043/"], "icd11_code": "LD2F"},
          {"name": "Marfan syndrome", "description": "Autosomal dominant connective tissue disorder affecting skeletal, ocular, and cardiovascular systems from FBN1 mutations.", "aliases": ["MFS", "Marfans disease"], "causes": ["mutations in FBN1 gene encoding fibrillin-1", "autosomal dominant; 25% de novo"], "symptoms": ["tall stature", "arachnodactyly", "pectus deformity", "lens dislocation (ectopia lentis)", "aortic root dilation", "mitral valve prolapse", "scoliosis"], "treatment": "Beta-blockers or losartan for aortic protection; prophylactic aortic root surgery when diameter exceeds 5cm; annual cardiac imaging", "prevalence": "1 in 5,000-10,000", "is_rare": 1, "sources": ["https://www.marfan.org/marfan/overview-and-diagnosis"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/20301295/"], "icd11_code": "LD28.1"},
          {"name": "Ehlers-Danlos syndrome", "description": "Heterogeneous group of heritable connective tissue disorders with joint hypermobility, skin hyperextensibility, and tissue fragility.", "aliases": ["EDS", "Cutis hyperelastica"], "causes": ["mutations in collagen genes (COL5A1 for classic type)", "hypermobile type: complex polygenic", "vascular type: COL3A1 mutations"], "symptoms": ["joint hypermobility and recurrent dislocations", "skin hyperextensibility and fragility", "abnormal scarring", "chronic pain", "vascular rupture in vascular EDS"], "treatment": "Physical therapy and joint protection; pain management; low-impact exercise; surgical repair for vascular EDS complications", "prevalence": "1 in 5,000 for classic EDS; hypermobile type more common", "is_rare": 1, "sources": ["https://www.niams.nih.gov/health-topics/ehlers-danlos-syndrome"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/28306229/"], "icd11_code": "LD28.0"},
          {"name": "Reactive arthritis", "description": "Sterile arthritis triggered by an infection elsewhere, classically in genitourinary or gastrointestinal tract.", "aliases": ["Reiters syndrome", "ReA", "Post-infectious arthritis"], "causes": ["triggered by Chlamydia trachomatis", "Salmonella", "Shigella", "Campylobacter infections", "HLA-B27 increases susceptibility"], "symptoms": ["asymmetric oligoarthritis", "urethritis", "conjunctivitis (classic triad)", "oral ulcers", "skin lesions: keratoderma blennorrhagicum"], "treatment": "NSAIDs for arthritis; antibiotics for active genital infection; sulfasalazine for chronic cases; corticosteroid injections", "prevalence": "0.1% after triggering infection", "is_rare": 0, "sources": ["https://www.niams.nih.gov/health-topics/reactive-arthritis"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/27133487/"], "icd11_code": "FA50"},
          {"name": "Psoriatic arthritis", "description": "Inflammatory arthritis in patients with psoriasis affecting peripheral joints, axial skeleton, and entheses.", "aliases": ["PsA", "Psoriasis arthropathy"], "causes": ["immune dysregulation in context of psoriasis", "HLA-B27 in axial disease", "TNF, IL-17, IL-23 pathway overactivation"], "symptoms": ["asymmetric oligoarthritis or symmetric polyarthritis", "dactylitis", "enthesitis", "axial disease", "nail psoriasis", "skin psoriasis plaques"], "treatment": "NSAIDs for mild disease; methotrexate; anti-TNF biologics; secukinumab, ixekizumab; ustekinumab; JAK inhibitors (tofacitinib)", "prevalence": "0.25% of population; affects 30% of psoriasis patients", "is_rare": 0, "sources": ["https://www.niams.nih.gov/health-topics/psoriatic-arthritis"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/27538824/"], "icd11_code": "FA93"},
          {"name": "Polymyalgia rheumatica", "description": "Inflammatory condition in older adults causing proximal muscle aching and stiffness without true myositis.", "aliases": ["PMR", "Senile rheumatic gout"], "causes": ["autoimmune; associated with giant cell arteritis in 15-20%", "HLA-DRB1*04 association"], "symptoms": ["bilateral shoulder and hip girdle aching and stiffness", "marked morning stiffness", "elevated ESR and CRP", "rapid dramatic response to low-dose prednisone"], "treatment": "Low-dose prednisone (15-20mg daily) with slow taper; tocilizumab for relapsing disease; screen for giant cell arteritis", "prevalence": "1 in 200 adults over 50 in UK", "is_rare": 0, "sources": ["https://www.niams.nih.gov/health-topics/polymyalgia-rheumatica-giant-cell-arteritis"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/26077378/"], "icd11_code": "FA22"}
