          {"name": "Erectile dysfunction", "description": "Persistent inability to achieve or maintain an erection sufficient for satisfactory sexual performance.", "aliases": ["ED", "Impotence", "Male sexual dysfunction"], "causes": ["vascular: atherosclerosis, hypertension, diabetes", "neurogenic: spinal cord injury, multiple sclerosis", "hormonal: hypogonadism", "psychological: depression, anxiety", "medications"], "symptoms": ["inability to achieve erection", "inability to maintain erection", "reduced sexual desire", "associated with cardiovascular risk factor profile"], "treatment": "PDE5 inhibitors (sildenafil, tadalafil) first-line; testosterone replacement if hypogonadal; vacuum erection device; penile prosthesis; psychosexual counseling", "prevalence": "52% of men 40-70 have some degree of ED", "is_rare": 0, "sources": ["https://www.niddk.nih.gov/health-information/urologic-diseases/erectile-dysfunction"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/26839063/"], "icd11_code": "HA00"},
          {"name": "Female sexual arousal disorder", "description": "Persistent difficulty with arousal including absent subjective or genital response to sexual stimulation.", "aliases": ["FSAD", "Female sexual dysfunction", "Genital arousal disorder"], "causes": ["hormonal: reduced estrogen postmenopause", "reduced genital blood flow", "psychological: anxiety, depression, trauma history", "relationship factors"], "symptoms": ["absent or markedly reduced vaginal lubrication", "absent subjective arousal feelings", "absent genital tingling or warmth", "associated distress"], "treatment": "Estrogen therapy for postmenopausal; mindfulness-based sex therapy; treatment of comorbid depression; flibanserin for premenopausal HSDD", "prevalence": "8-21% of women", "is_rare": 0, "sources": ["https://www.womenshealth.gov/mental-health/mental-health-conditions/sexual-dysfunction"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/27516305/"], "icd11_code": "HA01"},
          {"name": "Premature ejaculation", "description": "Male sexual dysfunction with ejaculation consistently occurring before or shortly after vaginal penetration causing distress.", "aliases": ["PE", "Rapid ejaculation", "Early ejaculation"], "causes": ["serotonin signaling dysregulation", "hypersensitivity of the glans", "psychological: performance anxiety", "genetic predisposition in lifelong PE"], "symptoms": ["ejaculation within 1 minute of penetration in lifelong PE", "inability to delay ejaculation", "marked distress and interpersonal difficulties"], "treatment": "Behavioral techniques: squeeze and stop-start; topical anesthetics; SSRIs (dapoxetine, off-label sertraline); PDE5 inhibitors as adjunct", "prevalence": "20-30% of men", "is_rare": 0, "sources": ["https://www.niddk.nih.gov/health-information/urologic-diseases"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/26479370/"], "icd11_code": "HA02"},
          {"name": "Dyspareunia", "description": "Recurrent genital pain during or after sexual intercourse in women or men.", "aliases": ["Painful intercourse", "Genito-pelvic pain disorder", "Coital pain"], "causes": ["female: vulvodynia, endometriosis, vaginismus, infections, atrophic vaginitis", "male: Peyronies disease, prostatitis, phimosis"], "symptoms": ["pain at entry or deep penetration", "burning, stabbing, or aching genital pain", "associated avoidance of sex and relationship distress"], "treatment": "Treat underlying cause; topical estrogen for atrophic vaginitis; pelvic floor physical therapy; lidocaine gel; psychosexual therapy", "prevalence": "8-22% of women; less commonly men", "is_rare": 0, "sources": ["https://www.womenshealth.gov/menstruation-and-your-cycle/sexual-pain-disorders"], "research_links": ["https://pubmed.ncbi.nlm.nih.gov/25948175/"], "icd11_code": "HA20"},
