DATA_ALL = DATA + DATA2 + DATA3 + DATA4 + DATA4B + DATA5

def main():
    if os.path.exists(DB_PATH):
        os.remove(DB_PATH)
    con = sqlite3.connect(DB_PATH)
    cur = con.cursor()

    cur.executescript("""
        CREATE TABLE IF NOT EXISTS nodes (
            id INTEGER PRIMARY KEY,
            parent_id INTEGER,
            level INTEGER,
            name TEXT,
            description TEXT,
            aliases TEXT,
            causes TEXT,
            symptoms TEXT,
            treatment TEXT,
            prevalence TEXT,
            is_rare INTEGER,
            sources TEXT,
            research_links TEXT,
            icd11_code TEXT
        );
        CREATE INDEX IF NOT EXISTS idx_nodes_parent ON nodes(parent_id);
        CREATE INDEX IF NOT EXISTS idx_nodes_name ON nodes(name);
        CREATE VIRTUAL TABLE IF NOT EXISTS nodes_fts USING fts5(
            name, description, aliases,
            content='nodes', content_rowid='id',
            tokenize='porter unicode61'
        );
    """)

    chapter_count = 0
    disease_count = 0

    for chapter_data in DATA_ALL:
        chapter_id = insert_node(
            cur, None, 0, chapter_data["chapter"], "", [], [], [], "", "", 0, [], [], ""
        )
        chapter_count += 1

        for block_data in chapter_data["blocks"]:
            block_id = insert_node(
                cur, chapter_id, 1, block_data["block"], "", [], [], [], "", "", 0, [], [], ""
            )

            for d in block_data["diseases"]:
                disease_id = insert_node(
                    cur, block_id, 2,
                    d["name"], d["description"],
                    d["aliases"], d["causes"], d["symptoms"],
                    d["treatment"], d["prevalence"], d["is_rare"],
                    d["sources"], d["research_links"], d["icd11_code"]
                )
                disease_count += 1

    cur.execute("""
        INSERT INTO nodes_fts(rowid, name, description, aliases)
        SELECT id, name, description, aliases FROM nodes WHERE level = 2
    """)

    con.commit()
    con.close()
    print(f"Seeded {chapter_count} chapters and {disease_count} diseases into {DB_PATH}")


if __name__ == "__main__":
    main()
